INSERT INTO client_releases (version, version_key, platform, file_key, file_name, size, sha256, notes, notes_en, published_at) VALUES ('2.93.1', 2093001, 'windows', 'releases/CosmicPlatformer-Setup-2.93.1.exe', 'CosmicPlatformer-Setup-2.93.1.exe', 160289593, '28af4fa9f5fd16d42b4fec496c197b8e1a02fc5be0d6dc50e2c4a80e995b0e2b', 'Version 2.93.1 :
